    "pub_date": "2026-11-04 21:17:47",
    "author": "",
    "description": "深秋的雨夜，铺开纸，抄几行诗。 最早接触诗词，是在父亲身边。晚饭之后，母亲收拾碗筷，父亲搬一张矮木凳坐到桌边。头顶一盏老式灯泡，光线发黄，照不远，但很暖。他从口袋里摸出一本翻得卷了边的旧书，慢悠悠地念给我听。 念“远看山有色，近听水无声”，念“沾衣欲湿杏花雨，吹面不寒杨柳风”，也读陆游的《咏梅》。有些句子我已经记不全了，只记得他念到某些地方，声音会慢下来，像是那几个字比别的字重一些，要含在嘴里多停一停。 父亲从来不解释，也不考我背没背会…",
    "content": "深秋的雨夜，铺开纸，抄几行诗。 最早接触诗词，是在父亲身边。晚饭之后，母亲收拾碗筷，父亲搬一张矮木凳坐到桌边。头顶一盏老式灯泡，光线发黄，照不远，但很暖。他从口袋里摸出一本翻得卷了边的旧书，慢悠悠地念给我听。 念“远看山有色，近听水无声”，念“沾衣欲湿杏花雨，吹面不寒杨柳风”，也读陆游的《咏梅》。有些句子我已经记不全了，只记得他念到某些地方，声音会慢下来，像是那几个字比别的字重一些，要含在嘴里多停一停。 父亲从来不解释，也不考我背没背会。那些诗句伴着饭桌上的烟火气，伴着灯泡嗡嗡的细响，一点一点渗进记忆里。 读中学那…"
