    "description": "做免疫相关课题的科研人，是不是都有过这种崩溃：同一份血清样本，三次IgG Fab检测结果差出20%，好不容易攒的小鼠实验数据，因为质控不达标被审稿人打回？我去年帮师姐处理过一批类风湿关节炎患者的血清样本，用某进口试剂盒测IgG Fab，前后重复测了12份样本，变异系数（CV）最高到18.7%，最后只能重新做实验，耽误了3个月的论文投稿。直到后来换了睿信生物的人免疫球蛋白G Fab（IgG Fab）检测试剂盒，才把检测误差彻底稳住。 作为…",
    "content": "做免疫相关课题的科研人，是不是都有过这种崩溃：同一份血清样本，三次IgG Fab检测结果差出20%，好不容易攒的小鼠实验数据，因为质控不达标被审稿人打回？我去年帮师姐处理过一批类风湿关节炎患者的血清样本，用某进口试剂盒测IgG Fab，前后重复测了12份样本，变异系数（CV）最高到18.7%，最后只能重新做实验，耽误了3个月的论文投稿。直到后来换了 睿信生物的人免疫球蛋白G Fab（IgG Fab）检测试剂盒 ，才把检测误差彻底稳住。 作为跟IgG检测打了5年交道的科研狗，我结合自己的实操经验和第三方质控数据，给大…"
