    "content": "新华社东京11月4日电（记者李子越 陈泽安）据日本时事社报道，在4日下午举行的日本参议院宪法审查会会议上，自民党再次呼吁加快推进修宪议题的讨论，但相关主张受到部分在野党的批评和反对。 报道说，在当天的会议上，自民党籍参议员北村经夫提及该党有关在宪法第九条中明确写入自卫队等修宪主张。他表示，日本迄今为止尚未就修宪的必要性征询国民意见，这“极不正常”，呼吁尽快推动相关讨论。 对此，立宪民主党籍参议员小西洋之表示，宪法基本原则具有普遍性。他强调要坚决反对错误的修宪主张，坚持运用宪法保护国民。 日本共产党政策委员长山添拓指…"
