    "content": "36氪获悉，统一股份公告，近日，统一低碳科技股份有限公司控股子公司统一石油化工有限公司与宁德时代新能源科技股份有限公司签订《冷却液战略合作协议》。宁德时代与统一石化共同研究冷却液的可靠性，包括影响因子研究、模型搭建、模型验证；统一石化开展低电导冷却液寿命检测技术及评价方法研究，并提供相关报告及技术咨询服务。通过双方的战略合作，因客户需求宁德时代会优先考虑统一石化开发的低电导冷却液产品（经双方认可），统一石化的产品应满足双方约定的技术规格要求和法律法规的规定。本协议自双方法定代表人或授权代表签字盖章后生效，有效期为本…"
