    "description": "新华社杭州11月4日电（记者魏一骏、顾小立）头戴黑色警帽、身着反光背心、指挥动作标准——在世界互联网大会乌镇峰会举办地浙江桐乡，身高一米八的机器人交警站在濮院镇一处交叉路口，吸引了不少过路车流和行人的目光。 “这是升级后上岗的机器人交警‘桐桐’，与去年初次亮相相比，今年它在外观和功能上都有了进一步提升。”桐乡市公安局交通管理大队濮院中队副中队长夏斌说。 从外观来看，“桐桐”底盘的万向轮从3个升级到4个，不仅稳定性更高，通行性能和移动速度…",
    "content": "新华社杭州11月4日电（记者魏一骏、顾小立）头戴黑色警帽、身着反光背心、指挥动作标准——在世界互联网大会乌镇峰会举办地浙江桐乡，身高一米八的机器人交警站在濮院镇一处交叉路口，吸引了不少过路车流和行人的目光。 “这是升级后上岗的机器人交警‘桐桐’，与去年初次亮相相比，今年它在外观和功能上都有了进一步提升。”桐乡市公安局交通管理大队濮院中队副中队长夏斌说。 从外观来看，“桐桐”底盘的万向轮从3个升级到4个，不仅稳定性更高，通行性能和移动速度也同步提升。除了激光雷达和摄像头，它的胸前还新增了一块交互屏，在岗时长最长可超8…"
