    "content": "新华社纽约11月4日电（记者杨士龙 施春）美国中期选举于11月3日举行。据美国媒体预测，民主党在选举中力压共和党重获国会参议院和众议院控制权。 分析人士认为，特朗普政府发起的“关税战”和对伊朗军事行动抬升美国国内物价和生活成本，引发选民不满，成为共和党选举惨败主要原因。随着民主党掌控国会两院，特朗普政府后续施政将面临更大阻力。 汹涌的“蓝潮” 美东时间3日18时起，全美范围内投票陆续结束。数小时后，舆论此前预判的“蓝潮”（蓝色和红色分别是民主党和共和党的代表色）逐渐显现，民主党候选人在各地接连赢得选举。至午夜，多家…"
