    "content": "新华社广州11月4日电（黄浩苑、黄国保）东莞市黛妃服饰有限公司的产线，已经迎来了广交会的第五批客人。总经理李润泽正在给海外客商讲解他的新产品，客商们对他将毛织纱线做成棉服及牛仔服的效果表示惊奇。 第140届广交会第三期聚焦“美好生活”主题，涵盖玩具及孕婴童、时尚、家用纺织品、文具、健康休闲5大板块。来自全球的采购商不仅在现场展位看样、洽谈，还纷纷走进工厂车间看生产线、验品质、谈定制，以“展+厂”的深度联动，积极促进外贸成交。 黛妃服饰今年才刚起步开拓海外市场，企业发现，加拿大、俄罗斯以及北欧多国对厚款保暖毛衣、大码…"
