    "content": "Apple Intelligence，苹果“正统 AI”，终于轮到国行了。两年了！你知道这两年国行用户是怎么过来的吗？！ 外人家的 iPhone 已经能写邮件、修照片、跟 AI 聊天了，我们的 Siri 还在兢兢业业地设闹钟。 今天凌晨，国行 Apple Intelligence 抢先版推送了，不过这次还是开发者测试版， 普通用户得等到 12 月。这回苹果请了个中国外援：阿里巴巴的千问。（那我以后喊 Siri，是不是相当于打开了千问？） 照片消除、通知摘要、文字改写等等，还是主要靠苹果自己的模型。千问则负责帮 Si…"
