    "description": "新华社北京11月4日电（记者丁乐）第140届中国进出口商品交易会（广交会）4日闭幕，记者从广交会承办方中国对外贸易中心了解到，截至3日，来自219个国家和地区的35.2万名境外采购商到会，较上届增长12.2%，规模再创历史新高。",
    "content": "新华社北京11月4日电（记者丁乐）第140届中国进出口商品交易会（广交会）4日闭幕，记者从广交会承办方中国对外贸易中心了解到，截至3日，来自219个国家和地区的35.2万名境外采购商到会，较上届增长12.2%，规模再创历史新高。"
