    "content": "新华社基多11月4日电 专访｜“以媒体互通协作构建人工智能时代真实立体叙事体系”——访厄瓜多尔公共通信公司总经理科尔德罗 新华社记者赵鑫虎 “面对人工智能时代媒体系统性变革与挑战，全球新闻机构应当深化互通协作，破除信息壁垒与传播偏见，通过技术赋能打造符合自身价值、真实立体的叙事体系。”厄瓜多尔公共通信公司总经理格拉斯·科尔德罗在赴华参加第七届世界媒体峰会前夕接受新华社记者专访时说。 “以厄瓜多尔所在的拉美地区为例，许多国际媒体涉拉美的报道长期以来多聚焦治安问题、社会危机与政治动荡，未能全面展现地区发展现状。其实，拉…"
