    "title": "从“制”到“智” 从“煤”到“美”：重庆万盛“十五五”谋划绿色低碳发展新路径",
    "link": "https://www.chinanews.com.cn/gn/2026/11-04/10726206.shtml",
    "pub_date": "2026-11-04 20:05:00",
    "author": "",
    "description": "中新网重庆11月4日电 (罗永皓)“十五五”时期，重庆市万盛经济技术开发区将推动产城景深度融合与城乡一体发展，加快打造区域中心城市、全国绿色低碳转型发展示范区、西部陆海新通道辐射带动先导区、成渝地区双城经济圈大健康旅游目的地，力争到2030年全区经济总量迈上400亿元新台阶。",
    "content": "中新网重庆11月4日电 (罗永皓)“十五五”时期，重庆市万盛经济技术开发区将推动产城景深度融合与城乡一体发展，加快打造区域中心城市、全国绿色低碳转型发展示范区、西部陆海新通道辐射带动先导区、成渝地区双城经济圈大健康旅游目的地，力争到2030年全区经济总量迈上400亿元新台阶。"
