    "content": "一直都用软件同步工具来同步自己的工作文档，因为涉及到办公的一些文档，所以不敢使用云端的厂家同步工具，而自建了 NAS 的私有同步。 多年前买了威联通的 NAS ，看到它有 QSync 的同步软件，看着做的还可以，所以就一直用到现在，应该用了有四五年了。但是之前就发现这个同步工具多端同步的时候，经常容易出现文件同步缺失。甚至是误删文件的情况。多端同步的话，比如家里的 Windows 电脑或者 Mac 电脑，以及办公室的 Windows 和 Mac 这样的多端版本相互同步的时候，有时候会发现一个文件在一个设备上，而在另…"
