    "content": "第九届中国国际进口博览会将于11月5日至10日在上海举办。根据近日发布的11月长三角绿电交易结果，第九届中国国际进口博览会场馆已达成11月全月绿电交易电量850万千瓦时，这一交易将助力第九届进博会实现全绿电零碳办展。 国网上海电力工作人员在国家会展中心（上海）现场指挥中心通过智慧保电系统查看现场供电服务保障情况。（受访者供图） 据介绍，场馆方通过参与跨经营区输电权和跨区绿电交易、长三角绿电和本地绿电市场等交易，首次实现多品种、多来源、多通道绿电交易组合，10月至11月场馆累计采购绿电超1500万千瓦时，覆盖展前、展…"
