    "content": "冰岛外交部长贡纳尔斯多蒂尔近日在北京接受新华社记者专访时表示，冰岛和中国在应对气候变化方面的合作为全世界作出了表率，证明国家无论大小，都可以通过携手合作为应对全人类共同挑战作出贡献。 今年是中冰建交55周年。2025年10月，国家主席习近平在北京会见冰岛总统托马斯多蒂尔时指出，中国和冰岛建交54年来，坚持相互尊重、互利合作，两国关系取得的丰硕成果充分证明，不同国情国家完全能够超越社会制度等差异实现互利共赢。 “我对此完全赞同。我读过习近平主席的许多论述，他是一位富有智慧的领导人。托马斯多蒂尔总统对去年访华时中国人民…"
