    "content": "新华社北京11月4日电（记者许晓静、陆烨）国务院台办4日举行例行新闻发布会。发言人朱凤莲回答在对台工作中如何贯彻落实党的二十届五中全会精神的提问时表示，解决台湾问题、实现祖国完全统一，是实现中华民族伟大复兴的必然要求，是中国共产党矢志不渝的历史任务。对台工作是党和国家事业的重要组成部分。我们将深入学习宣传贯彻二十届五中全会精神，全面贯彻落实习近平总书记关于对台工作的重要论述和新时代党解决台湾问题的总体方略，坚持党的全面领导和党中央集中统一领导，以管党治党、兴党强党新成效引领对台工作高质量发展，团结广大台湾同胞共同推…"
