    "content": "新华社曼谷11月4日电 专访｜期待借进博会进一步融入中国产供链——访中国泰国商会副会长庄派吉 新华社记者夏康静 “对泰国企业来说，进博会是进入中国市场的一扇大门。”中国泰国商会副会长庄派吉近日在曼谷接受新华社记者专访时说，他期待更多泰国企业借助这一平台进入中国市场，进一步融入中国产业链、供应链，实现长期发展。 多次参加进博会的庄派吉用“特别”“机会”“开放”三个词形容进博会：世界上首个以进口为主题的国家级博览会，这是进博会的特别之处；既吸引大企业，也为小企业提供机会；向世界各国开放，寻求合作共赢。 他说，进博会是提…"
