    "description": "36氪获悉，东阳光公告，控股股东深圳市东阳光实业发展有限公司于2026年10月26日至11月4日通过集中竞价方式增持公司股份2528.44万股，占总股本0.84%，增持金额5.97亿元（不含交易费用）。本次增持计划尚未实施完毕；增持后，深圳东阳光实业及其一致行动人合计持股比例由53.48%升至54.32%，权益变动触及1%刻度。",
    "content": "36氪获悉，东阳光公告，控股股东深圳市东阳光实业发展有限公司于2026年10月26日至11月4日通过集中竞价方式增持公司股份2528.44万股，占总股本0.84%，增持金额5.97亿元（不含交易费用）。本次增持计划尚未实施完毕；增持后，深圳东阳光实业及其一致行动人合计持股比例由53.48%升至54.32%，权益变动触及1%刻度。"
