    "content": "新华社成都11月4日电（记者董小红）记者4日从四川省卫生健康委员会、四川省疾病预防控制中心获悉，经过国家疾病预防控制局会同多部门确认，四川已消除血吸虫病。 记者了解到，四川省曾经是我国血吸虫病重流行省份之一。新中国成立以来，四川始终将血吸虫防治工作列为重点民生工程。2025年，四川在全国7个重流行省中率先通过国家血吸虫病省级消除技术评估；2026年，国家多部门正式发文，确认四川省达到血吸虫病消除状态。 四川省血吸虫病的消除，是多部门协同治理的成果。四川省委、省政府始终将血防工作作为重大民生工程和公共卫生底线任务，持…"
