    "content": "新华社宁波11月4日电（记者方问禹、许舜达）11月2日至5日，由国务院新闻办公室指导、以“开放融通·共生机遇”为主题的“2026世界市长对话·宁波”活动在浙江省宁波市举办。来自15个国家20个城市的市长、市长代表，以及国际组织、企业代表等260余人齐聚东海之滨，围绕产业协作、贸易开放、人文相通等议题交流。 本次活动设一场主活动、两场情景对话和三场文明交流互鉴活动。在主活动上，14个合作项目集中签约，涉及友好交流、经贸合作、科技教育、文化旅游等领域；宁波市鄞州区与法国圣艾蒂安-迪鲁夫赖市、宁波余姚市与摩洛哥拉希迪耶市…"
