    "description": "",
    "content": "快科技11月4日消息，“四川发布”今日重磅 官宣 ： 近期，国家疾控局会同多部门正式印发通知，确认四川省达到血吸虫病消除状态 。 四川省曾经是我国血吸虫病重流行省之一，疫情曾波及成都、眉山、德阳、绵阳、乐山、雅安、凉山、资阳、攀枝花、宜宾、内江等11个市（州）的63个县（市、区），受威胁人口达1300余万。 于1924年首次报告血吸虫病病例，1939年发现钉螺，1943年证实耕牛感染，历史累计病人达127.57万人，晚期病人3万余人，历史病牛20万余头。 据了解，血吸虫病是由血吸虫寄生引起的人兽共患传染病，在我国流…"
